(function(w,d){"use strict";w.impress=function(id){var root=d.getElementById(id)||d.querySelector(".impress"),steps=[],active=0;function fitScale(){return Math.min(Math.max((w.innerWidth-32)/1280,.2),Math.max((w.innerHeight-90)/720,.2),1)}function place(el){var x=Number(el.dataset.x||0),y=Number(el.dataset.y||0),s=Number(el.dataset.scale||1),r=Number(el.dataset.rotate||0);el.style.setProperty("--step-x",x+"px");el.style.setProperty("--step-y",y+"px");el.style.setProperty("--step-scale",s);el.style.setProperty("--step-rotate",r+"deg")}function go(target){var next=typeof target==="number"?target:steps.indexOf(target);if(next<0||next>=steps.length)return null;active=next;steps.forEach(function(el,i){el.classList.toggle("is-active",i===active);el.setAttribute("aria-current",i===active?"step":"false")});var el=steps[active],x=Number(el.dataset.x||0),y=Number(el.dataset.y||0),s=Number(el.dataset.scale||1),r=Number(el.dataset.rotate||0);root.style.setProperty("--view-x",-x+"px");root.style.setProperty("--view-y",-y+"px");root.style.setProperty("--view-scale",fitScale()/s);root.style.setProperty("--view-rotate",-r+"deg");return el}return{init:function(){steps=Array.prototype.slice.call(root.querySelectorAll(".step"));steps.forEach(place);d.documentElement.classList.remove("no-js");d.documentElement.classList.add("js");d.body.classList.remove("no-motion");d.body.classList.add("spatial-ready");w.addEventListener("resize",function(){go(active)});return go(0)},goto:go,next:function(){return go(Math.min(active+1,steps.length-1))},prev:function(){return go(Math.max(active-1,0))},steps:function(){return steps.slice()},index:function(){return active}}}})(window,document);
